/* ---- basis --------------------------------------------------------------
 * The heap-allocated struct gkyl_basis is plain data filled by the in-place
 * initializers; the function pointers it carries are dispatched HERE, in
 * compiled code, never from the interpreter. */
gpython_basis *
gpython_basis_new(const char *type, int ndim, int poly_order)
{
  struct gkyl_basis *b = malloc(sizeof(struct gkyl_basis));
  if (strcmp(type, "serendipity") == 0) {
    gkyl_cart_modal_serendip(b, ndim, poly_order);
  } else if (strcmp(type, "tensor") == 0) {
    gkyl_cart_modal_tensor(b, ndim, poly_order);
  } else {
    free(b);
    return NULL;
  }
  return (gpython_basis *)b;
}

gpython_basis *
gpython_basis_new_hybrid(const char *type, int cdim, int vdim)
{
  struct gkyl_basis *b = malloc(sizeof(struct gkyl_basis));
  if (strcmp(type, "hybrid") == 0) {
    gkyl_cart_modal_hybrid(b, cdim, vdim);
  } else if (strcmp(type, "gkhybrid") == 0) {
    gkyl_cart_modal_gkhybrid(b, cdim, vdim);
  } else {
    free(b);
    return NULL;
  }
  return (gpython_basis *)b;
}

void
gpython_basis_release(gpython_basis *b)
{
  free(b);
}

int
gpython_basis_ndim(const gpython_basis *b)
{
  return (int)CBAS(b)->ndim;
}

int
gpython_basis_poly_order(const gpython_basis *b)
{
  return (int)CBAS(b)->poly_order;
}

int
gpython_basis_num_basis(const gpython_basis *b)
{
  return (int)CBAS(b)->num_basis;
}

const char *
gpython_basis_id(const gpython_basis *b)
{
  return CBAS(b)->id;
}

void
gpython_basis_eval(const gpython_basis *b, const double *z, double *bvals)
{
  CBAS(b)->eval(z, bvals);
}

void
gpython_basis_node_list(const gpython_basis *b, double *coords)
{
  CBAS(b)->node_list(coords);
}

void
gpython_basis_nodal_to_modal(const gpython_basis *b, const double *fnodal, double *fmodal)
{
  CBAS(b)->nodal_to_modal(fnodal, fmodal);
}

/* ---- weak (DG) algebra --------------------------------------------------
 * Arrays hold nfields = ncomp/num_basis DG fields side by side; the c_oop
 * arguments of the gkyl entry points are FIELD indices. The basis struct is
 * passed BY VALUE, exactly as the header declares — the compiler, not a
 * hand-written mirror, guarantees the ABI. */
static int
nfields_of(const gpython_basis *b, const gpython_array *a)
{
  size_t nb = (size_t)CBAS(b)->num_basis;
  if (CARR(a)->ncomp % nb != 0) {
    return -1;
  }
  return (int)(CARR(a)->ncomp / nb);
py_basis_info(PyObject *self, PyObject *args)
{
  PyObject *cap;
  if (!PyArg_ParseTuple(args, "O", &cap))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  return Py_BuildValue("(iiis)", gpython_basis_ndim(b),
                       gpython_basis_poly_order(b), gpython_basis_num_basis(b),
                       gpython_basis_id(b));
}

static PyObject *
py_basis_eval(PyObject *self, PyObject *args)
{
  PyObject *cap, *zobj;
  if (!PyArg_ParseTuple(args, "OO", &cap, &zobj))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  PyArrayObject *z =
      (PyArrayObject *)PyArray_FROM_OTF(zobj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
  if (!z)
    return NULL;
  if (PyArray_SIZE(z) < gpython_basis_ndim(b)) {
    Py_DECREF(z);
    PyErr_SetString(PyExc_ValueError, "point has fewer entries than ndim");
    return NULL;
  }
  npy_intp nb = gpython_basis_num_basis(b);
  PyObject *out = PyArray_SimpleNew(1, &nb, NPY_DOUBLE);
  if (!out) {
    Py_DECREF(z);
    return NULL;
  }
  gpython_basis_eval(b, PyArray_DATA(z), PyArray_DATA((PyArrayObject *)out));
  Py_DECREF(z);
  return out;
}

static PyObject *
py_basis_node_list(PyObject *self, PyObject *args)
{
  PyObject *cap;
  if (!PyArg_ParseTuple(args, "O", &cap))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  npy_intp dims[2] = {gpython_basis_num_basis(b), gpython_basis_ndim(b)};
  PyObject *out = PyArray_SimpleNew(2, dims, NPY_DOUBLE);
  if (!out)
    return NULL;
  gpython_basis_node_list(b, PyArray_DATA((PyArrayObject *)out));
  return out;
}

static PyObject *
py_basis_nodal_to_modal(PyObject *self, PyObject *args)
{
  PyObject *cap, *fobj;
  if (!PyArg_ParseTuple(args, "OO", &cap, &fobj))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  PyArrayObject *fin =
      (PyArrayObject *)PyArray_FROM_OTF(fobj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
  if (!fin)
    return NULL;
  npy_intp nb = gpython_basis_num_basis(b);
  if (PyArray_SIZE(fin) != nb) {
    Py_DECREF(fin);
    PyErr_SetString(PyExc_ValueError, "expected num_basis nodal values");
    return NULL;
  }
  PyObject *out = PyArray_SimpleNew(1, &nb, NPY_DOUBLE);
  if (!out) {
    Py_DECREF(fin);
    return NULL;
  }
  gpython_basis_nodal_to_modal(b, PyArray_DATA(fin),
                               PyArray_DATA((PyArrayObject *)out));
  Py_DECREF(fin);
  return out;
}

