/* ---- basis --------------------------------------------------------------
 * The heap-allocated struct gkyl_basis is plain data filled by the in-place
 * initializers; the function pointers it carries are dispatched HERE, in
 * compiled code, never from the interpreter. */
gpython_basis *
gpython_basis_new(const char *type, int ndim, int poly_order)
{
  struct gkyl_basis *b = malloc(sizeof(struct gkyl_basis));
  if (strcmp(type, "serendipity") == 0) {
    gkyl_cart_modal_serendip(b, ndim, poly_order);
  } else if (strcmp(type, "tensor") == 0) {
    gkyl_cart_modal_tensor(b, ndim, poly_order);
  } else {
    free(b);
    return NULL;
  }
  return (gpython_basis *)b;
}

gpython_basis *
gpython_basis_new_hybrid(const char *type, int cdim, int vdim)
{
  struct gkyl_basis *b = malloc(sizeof(struct gkyl_basis));
  if (strcmp(type, "hybrid") == 0) {
    gkyl_cart_modal_hybrid(b, cdim, vdim);
  } else if (strcmp(type, "gkhybrid") == 0) {
    gkyl_cart_modal_gkhybrid(b, cdim, vdim);
  } else {
    free(b);
    return NULL;
  }
  return (gpython_basis *)b;
}

void
gpython_basis_release(gpython_basis *b)
{
  free(b);
}

int
gpython_basis_ndim(const gpython_basis *b)
{
  return (int)CBAS(b)->ndim;
}

int
gpython_basis_poly_order(const gpython_basis *b)
{
  return (int)CBAS(b)->poly_order;
}

int
gpython_basis_num_basis(const gpython_basis *b)
{
  return (int)CBAS(b)->num_basis;
}

const char *
gpython_basis_id(const gpython_basis *b)
{
  return CBAS(b)->id;
}

void
gpython_basis_eval(const gpython_basis *b, const double *z, double *bvals)
{
  CBAS(b)->eval(z, bvals);
}

void
gpython_basis_node_list(const gpython_basis *b, double *coords)
{
  CBAS(b)->node_list(coords);
}

void
gpython_basis_nodal_to_modal(const gpython_basis *b, const double *fnodal, double *fmodal)
{
  CBAS(b)->nodal_to_modal(fnodal, fmodal);
}

/* ---- weak (DG) algebra --------------------------------------------------
 * Arrays hold nfields = ncomp/num_basis DG fields side by side; the c_oop
 * arguments of the gkyl entry points are FIELD indices. The basis struct is
 * passed BY VALUE, exactly as the header declares — the compiler, not a
 * hand-written mirror, guarantees the ABI. */
static int
nfields_of(const gpython_basis *b, const gpython_array *a)
{
  size_t nb = (size_t)CBAS(b)->num_basis;
  if (CARR(a)->ncomp % nb != 0) {
    return -1;
  }
  return (int)(CARR(a)->ncomp / nb);
py_basis_info(PyObject *self, PyObject *args)
{
  PyObject *cap;
  if (!PyArg_ParseTuple(args, "O", &cap))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  return Py_BuildValue("(iiis)", gpython_basis_ndim(b),
                       gpython_basis_poly_order(b), gpython_basis_num_basis(b),
                       gpython_basis_id(b));
}

static PyObject *
py_basis_eval(PyObject *self, PyObject *args)
{
  PyObject *cap, *zobj;
  if (!PyArg_ParseTuple(args, "OO", &cap, &zobj))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  PyArrayObject *z =
      (PyArrayObject *)PyArray_FROM_OTF(zobj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
  if (!z)
    return NULL;
  if (PyArray_SIZE(z) < gpython_basis_ndim(b)) {
    Py_DECREF(z);
    PyErr_SetString(PyExc_ValueError, "point has fewer entries than ndim");
    return NULL;
  }
  npy_intp nb = gpython_basis_num_basis(b);
  PyObject *out = PyArray_SimpleNew(1, &nb, NPY_DOUBLE);
  if (!out) {
    Py_DECREF(z);
    return NULL;
  }
  gpython_basis_eval(b, PyArray_DATA(z), PyArray_DATA((PyArrayObject *)out));
  Py_DECREF(z);
  return out;
}

static PyObject *
py_basis_node_list(PyObject *self, PyObject *args)
{
  PyObject *cap;
  if (!PyArg_ParseTuple(args, "O", &cap))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  npy_intp dims[2] = {gpython_basis_num_basis(b), gpython_basis_ndim(b)};
  PyObject *out = PyArray_SimpleNew(2, dims, NPY_DOUBLE);
  if (!out)
    return NULL;
  gpython_basis_node_list(b, PyArray_DATA((PyArrayObject *)out));
  return out;
}

static PyObject *
py_basis_nodal_to_modal(PyObject *self, PyObject *args)
{
  PyObject *cap, *fobj;
  if (!PyArg_ParseTuple(args, "OO", &cap, &fobj))
    return NULL;
  gpython_basis *b = basis_arg(cap);
  if (!b)
    return NULL;
  PyArrayObject *fin =
      (PyArrayObject *)PyArray_FROM_OTF(fobj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
  if (!fin)
    return NULL;
  npy_intp nb = gpython_basis_num_basis(b);
  if (PyArray_SIZE(fin) != nb) {
    Py_DECREF(fin);
    PyErr_SetString(PyExc_ValueError, "expected num_basis nodal values");
    return NULL;
  }
  PyObject *out = PyArray_SimpleNew(1, &nb, NPY_DOUBLE);
  if (!out) {
    Py_DECREF(fin);
    return NULL;
  }
  gpython_basis_nodal_to_modal(b, PyArray_DATA(fin),
                               PyArray_DATA((PyArrayObject *)out));
  Py_DECREF(fin);
  return out;
}

/* ------------------------------------------------------ weak DG algebra */
typedef int (*binop_fn)(const gpython_basis *, gpython_array *,
                        const gpython_array *, const gpython_array *);

"""The value_form verbs -- explicit modal · nodal · quad changes + ``apply``.

Conversions are **never implicit** (REFACTOR_GKEYLL_FFI.md §3b): these verbs are
the only way a dataset changes value_form, and each one stamps
``ctx["value_form"]`` (and ``ctx["num_quad"]`` for quad data) so ``info``
always shows what the numbers mean. All of them keep the data gkyl-native.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from postgkyl import dg

if TYPE_CHECKING:
  from postgkyl.gdatastate.gdatastate import GDataState

VALUE_FORMS = ("modal", "nodal", "quad")


def _native_basis(data: "GDataState"):
  """(basis_type, ndim, poly_order) for a gkyl-backed dataset, or raise."""
  if data.backend != "gkyl":
    raise ValueError(
        "value_form changes act on native (gkyl-backed) DG data; "
        "this dataset is NumPy-backed (already interpolated, or loaded "
        "without the Gkeyll library).")
  basis_type = data.ctx.get("basis_type")
  poly_order = data.ctx.get("poly_order")
  if basis_type is None or poly_order is None:
    raise ValueError("dataset has no basis_type/poly_order metadata")
  return str(basis_type), data.num_dims, int(poly_order)


def represent(data: "GDataState",
              *,
              to: str,
              num_quad: int | None = None,
              inplace: bool = False,
              tag: str | None = None,
              label: str | None = None):
  """Convert a native dataset to the ``to`` value_form (explicitly).

  ``modal`` <-> ``nodal`` is exact; ``modal`` -> ``quad`` evaluates at
  ``num_quad`` (default ``p+1``) Gauss–Legendre points per dimension;
  ``quad`` -> ``modal`` projects back with the rule the data was made with.
  ``nodal`` <-> ``quad`` composes through modal.

  Args:
    data: Native dataset to convert.
    to: Target value representation.
    num_quad: Gauss points per direction for quadrature representation.
    inplace: Mutate and return ``data`` instead of creating a dataset.
    tag: Optional tag for the returned dataset.
    label: Optional label for the returned dataset.
  """
  if to not in VALUE_FORMS:
    raise ValueError(f"unknown value_form '{to}'; "
                     f"choices: {VALUE_FORMS}")
  basis_type, ndim, poly_order = _native_basis(data)
  cur = data.ctx.get("value_form", "modal")
  arr = data.native

  if cur != to:
    if cur == "nodal":  # leave nodal (exact)
      arr = dg.rep.nodal_to_modal(basis_type, ndim, poly_order, arr)
    elif cur == "quad":  # leave quad (projection, with the data's own rule)
      nq = data.ctx.get("num_quad")
      if nq is None:
        raise ValueError("quad-represented dataset lost its 'num_quad' ctx")
      arr = dg.rep.quad_to_modal(basis_type, ndim, poly_order, arr, int(nq))
    # arr is now modal
    if to == "nodal":
      arr = dg.rep.modal_to_nodal(basis_type, ndim, poly_order, arr)
    elif to == "quad":
      nq = int(num_quad) if num_quad else poly_order + 1
      arr = dg.rep.modal_to_quad(basis_type, ndim, poly_order, arr, nq)
  else:
    arr = arr.clone()

  return data._result(data.grid,
                      arr,
                      inplace=inplace,
                      tag=tag,
                      label=label,
                      value_form=to,
                      num_quad=(int(num_quad) if num_quad else poly_order +
                                1) if to == "quad" else None)


def apply(data: "GDataState",
          fn,
          *,
          num_quad: int | None = None,
          inplace: bool = False,
          tag: str | None = None,
          label: str | None = None):
  """Apply ``fn`` pointwise via quadrature: modal -> quad -> fn -> modal.

  The explicit spelling of nonlinear pointwise operations on DG data (e.g.
  ``d.apply(np.sqrt)``): evaluate at ``num_quad`` (default ``p+1``) Gauss
  points, apply ``fn`` to the values, project back onto the basis. The result
  stays modal and gkyl-native; the projection is exact when ``fn(f)·b_j`` has
  degree ≤ 2·num_quad−1 -- raise ``num_quad`` to de-alias.

  Args:
    data: Native modal dataset to transform.
    fn: Python callable applied to the quadrature-point values.
    num_quad: Gauss points per dimension; defaults to ``poly_order + 1``.
    inplace: Mutate and return ``data`` instead of creating a dataset.
    tag: Optional tag for the returned dataset.
    label: Optional label for the returned dataset.

  Returns:
    A modal dataset containing the projected pointwise result.

  Raises:
    ValueError: If ``data`` is not native modal data or lacks basis metadata.
  """
  basis_type, ndim, poly_order = _native_basis(data)
  if data.ctx.get("value_form", "modal") != "modal":
    raise ValueError("apply() expects modal data; call .to_modal() first.")
  nq = int(num_quad) if num_quad else poly_order + 1
  out = dg.rep.apply_pointwise(basis_type, ndim, poly_order, data.native, fn,
                               nq)
  return data._result(data.grid,
                      out,
                      inplace=inplace,
                      tag=tag,
                      label=label,
                      applied=getattr(fn, "__name__", str(fn)),
                      applied_num_quad=nq)

