  vals = fn(quad.view())
  vals = np.asarray(vals, dtype=np.float64)
  if vals.shape != (quad.size, quad.ncomp):
    raise ValueError(
        f"apply(fn): fn changed the shape {(quad.size, quad.ncomp)} -> "
        f"{vals.shape}; it must act pointwise.")
