  assert out.shape == (2 * 3, 1)  # 2 tensor nodes/cell * 3 cells, 1 field
  np.testing.assert_allclose(np.sort(out[:, 0].reshape(3, 2), axis=1),
                             np.sort(nodal.view(), axis=1),
                             atol=1e-13)
