static void check(gpython_basis *basis)
{
  int nb = gpython_basis_num_basis(basis);
  int nq = gpython_basis_num_quad(basis);
  double *modal = calloc(nb, sizeof(double));
  double *quad = calloc(nq, sizeof(double));
  double *back = calloc(nb, sizeof(double));
  for (int j = 0; j < nb; ++j) {
    modal[j] = 1.;
    assert(gpython_basis_modal_to_quad(basis, modal, quad) == 0);
    assert(gpython_basis_quad_to_modal(basis, quad, back) == 0);
    for (int k = 0; k < nb; ++k) assert(fabs(back[k] - modal[k]) < 1.e-12);
    modal[j] = 0.;
  }
  free(modal); free(quad); free(back);
  gpython_basis_release(basis);
}
int main(void)
{
  for (int cdim = 1; cdim <= 3; ++cdim) {
    for (int vdim = 1; vdim <= 3; ++vdim)
      check(gpython_basis_new_hybrid("hybrid", cdim, vdim));
    check(gpython_basis_new_hybrid("gkhybrid", cdim, 2));
  }
  check(gpython_basis_new_hybrid("gkhybrid", 1, 1));
  for (int ndim = 1; ndim <= 4; ++ndim) {
    check(gpython_basis_new("serendipity", ndim, 2));
    check(gpython_basis_new("tensor", ndim, 2));
  }
  return 0;
}
